import logo from './logo.svg';
import './App.css';

function App() {
  return (
    <div className='App'>
      <header className="App-header">
        <div class="hgroup">
          <h1>TropicSea Adventures</h1>
          <h2>Sea Creature Classification</h2>
        </div>
      </header>
      <div>
        <table className="table table-hover">
          <thead>
            <tr>
              <th scope='col'>Upload</th>
              <th scope='col'>Identification</th>
            </tr>
          </thead>
        </table>
      </div>
    </div>
  );
}

export default App;
